import React, { PropsWithChildren } from 'react';

import { ColumnOrder } from './ColumnOrder.js';
import { CopyItem } from './CopyItem.js';
import { FontStyle } from './FontStyle.js';
import { HideColumn } from './HideColumn.js';
import { LineWrap } from './LineWrap.js';
import { Menu } from '../../../../navigation/menu/Menu.js';

const _TableUserActions = ({ children }: PropsWithChildren) => <>{children}</>; // eslint-disable-line react/jsx-no-useless-fragment

_TableUserActions['displayName'] = 'TableUserActions';

// The following components are simply remapped from the Menu to provide a nice API on the Table
// and allow the slots to work for the Menu component. The slots check for equality of the function
// and therefore wrapping the Menu.Group for instance would yield a different function and therefore
// break the slotting behavior inside the Menu.

const Group = Menu.Group;
const Item = Menu.Item;
const Label = Menu.Label;
const ItemIcon = Menu.ItemIcon;

/** Configuration component defining user actions for a column or cell in the DataTable. */
export const TableUserActions = Object.assign(_TableUserActions, {
  /** The Group component allows you to group actions together semantically. */
  Group,
  /** The Item component allows you to provide single actions. */
  Item,
  /** The ItemIcon component allows you add icons within your action items. */
  ItemIcon,
  /** The Label component allows you to create non interactive labels within your actions. */
  Label,
  /** The LineWrap component can be added to column actions to allow the user to toggle line wrap for the column. */
  LineWrap,
  /** The HideColumn component can be added to the column actions to allow the user to hide the respective column */
  HideColumn,
  /** The CopyItem component can be added to cell actions to allow the user to copy the content of the current cell. */
  CopyItem,
  /** The FontStyle component can be added to column actions to allow the user to change the font of current column. */
  FontStyle,
  /** The ColumnOrder component can be added to column actions to allow the user to change the order of current column. */
  ColumnOrder,
});
